  const saved: SavedMedia[] = [];
  let inlineIndex = 0;
  let offloadedIndex = 0;
  for (const entry of params.imageOrder) {
    if (entry === "offloaded") {
      const ref = params.offloadedRefs[offloadedIndex++];
      if (!ref) {
        continue;
